package main

import (
	"sync"
	"time"
)

type Usuario struct {
	ID    string `json:"id"`
	Nome  string `json:"nome"`
	Papel string `json:"papel"`
}

type Sala struct {
	ID         string `json:"id"`
	Nome       string `json:"nome"`
	Capacidade int    `json:"capacidade"`
}

type Store struct {
	mu      sync.RWMutex
	Relogio time.Time
	Usuarios map[string]Usuario
	Salas    map[string]Sala
}

func NewStore() *Store {
	s := &Store{}
	s.Reset()
	return s
}

func (s *Store) Reset() {
	s.mu.Lock()
	defer s.mu.Unlock()

	loc, _ := time.LoadLocation("America/Sao_Paulo")
	if loc == nil {
		// Fallback caso o sistema não tenha o fuso, usamos o offset fixo de -03:00
		loc = time.FixedZone("BRT", -3*60*60)
	}
	s.Relogio = time.Date(2026, 10, 13, 9, 0, 0, 0, loc)

	s.Usuarios = map[string]Usuario{
		"org-ana":    {"org-ana", "Ana Beatriz Lima", "organizacao"},
		"org-bruno":  {"org-bruno", "Bruno Tavares", "organizacao"},
		"p-carla":    {"p-carla", "Carla Mendes Souza", "participante"},
		"p-diego":    {"p-diego", "Diego Alves", "participante"},
		"p-elisa":    {"p-elisa", "Elisa Fernandes da Rocha", "participante"},
		"p-fabio":    {"p-fabio", "Fábio Nogueira", "participante"},
		"p-gabriela": {"p-gabriela", "Gabriela Moura Castro", "participante"},
		"p-heitor":   {"p-heitor", "Heitor Campos", "participante"},
		"p-isadora":  {"p-isadora", "Isadora Ribeiro dos Santos", "participante"},
		"p-joao":     {"p-joao", "João Pedro Martins", "participante"},
	}

	s.Salas = map[string]Sala{
		"auditorio": {"auditorio", "Auditório Central", 200},
		"sala-101":  {"sala-101", "Sala 101", 40},
		"sala-102":  {"sala-102", "Sala 102", 40},
		"lab-3":     {"lab-3", "Laboratório 3", 20},
	}
}

func (s *Store) GetAgora() time.Time {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.Relogio
}

func (s *Store) SetRelogio(t time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.Relogio = t
}

package main

import (
	"encoding/json"
	"net/http"
	"time"
)

func handleReset(s *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Método não permitido", http.StatusMethodNotAllowed)
			return
		}
		s.Reset()
		w.WriteHeader(http.StatusNoContent)
	}
}

func handleRelogio(s *Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			agora := s.GetAgora()
			json.NewEncoder(w).Encode(map[string]string{
				"agora": agora.Format(time.RFC3339),
			})

		case http.MethodPut:
			var body struct {
				Agora string `json:"agora"`
			}
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				w.WriteHeader(http.StatusUnprocessableEntity)
				json.NewEncoder(w).Encode(map[string]string{
					"erro": "DADOS_INVALIDOS",
					"mensagem": "Corpo JSON inválido",
				})
				return
			}

			t, err := time.Parse(time.RFC3339, body.Agora)
			if err != nil {
				w.WriteHeader(http.StatusUnprocessableEntity)
				json.NewEncoder(w).Encode(map[string]string{
					"erro": "DADOS_INVALIDOS",
					"mensagem": "Formato de data inválido",
				})
				return
			}

			s.SetRelogio(t)
			json.NewEncoder(w).Encode(map[string]string{
				"agora": t.Format(time.RFC3339),
			})

		default:
			http.Error(w, "Método não permitido", http.StatusMethodNotAllowed)
		}
	}
}

package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	modoTeste := os.Getenv("MODO_TESTE") == "1"
	store := NewStore()

	mux := http.NewServeMux()

	if modoTeste {
		mux.HandleFunc("/_teste/reset", handleReset(store))
		mux.HandleFunc("/_teste/relogio", handleRelogio(store))
	} else {
		// No modo normal, essas rotas devem retornar 404
		// O default ServeMux já faria isso se não registrarmos, 
		// mas para ser explícito em caso de outros handlers:
		mux.HandleFunc("/_teste/", func(w http.ResponseWriter, r *http.Request) {
			http.NotFound(w, r)
		})
	}

	// Handlers básicos para verificação
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		fmt.Fprintln(w, "OK")
	})

	fmt.Printf("Servidor rodando na porta %s (MODO_TESTE=%v)\n", port, modoTeste)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func TestModoTeste(t *testing.T) {
	// Garantir que MODO_TESTE está ativo para este teste
	os.Setenv("MODO_TESTE", "1")
	defer os.Unsetenv("MODO_TESTE")

	store := NewStore()
	mux := http.NewServeMux()
	mux.HandleFunc("/_teste/reset", handleReset(store))
	mux.HandleFunc("/_teste/relogio", handleRelogio(store))

	t.Run("GET /_teste/relogio retorna hora inicial", func(t *testing.T) {
		req := httptest.NewRequest("GET", "/_teste/relogio", nil)
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)

		if rec.Code != http.StatusOK {
			t.Errorf("esperava 200, recebeu %d", rec.Code)
		}

		var resp map[string]string
		json.Unmarshal(rec.Body.Bytes(), &resp)

		esperado := "2026-10-13T09:00:00-03:00"
		if resp["agora"] != esperado {
			t.Errorf("esperava %s, recebeu %s", esperado, resp["agora"])
		}
	})

	t.Run("PUT /_teste/relogio altera o tempo", func(t *testing.T) {
		novaHora := "2026-10-19T10:00:00Z"
		body, _ := json.Marshal(map[string]string{"agora": novaHora})
		req := httptest.NewRequest("PUT", "/_teste/relogio", bytes.NewBuffer(body))
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)

		if rec.Code != http.StatusOK {
			t.Errorf("esperava 200, recebeu %d", rec.Code)
		}

		var resp map[string]string
		json.Unmarshal(rec.Body.Bytes(), &resp)

		// O Go pode formatar com Z ou -00:00 dependendo do parsing, 
		// mas o instante deve ser o mesmo.
		t1, _ := time.Parse(time.RFC3339, novaHora)
		t2, _ := time.Parse(time.RFC3339, resp["agora"])
		if !t1.Equal(t2) {
			t.Errorf("esperava %v, recebeu %v", t1, t2)
		}
	})

	t.Run("POST /_teste/reset restaura estado", func(t *testing.T) {
		// Altera primeiro
		store.SetRelogio(time.Now())

		req := httptest.NewRequest("POST", "/_teste/reset", nil)
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)

		if rec.Code != http.StatusNoContent {
			t.Errorf("esperava 204, recebeu %d", rec.Code)
		}

		esperado := "2026-10-13T09:00:00-03:00"
		agora := store.GetAgora().Format(time.RFC3339)
		if agora != esperado {
			t.Errorf("esperava %s, recebeu %s", esperado, agora)
		}
	})
}

func TestModoTesteDesativado(t *testing.T) {
	// Garantir que MODO_TESTE está desativado
	os.Setenv("MODO_TESTE", "0")
	defer os.Unsetenv("MODO_TESTE")

	// Precisamos simular como o main.go configura o mux
	store := NewStore()
	mux := http.NewServeMux()
	// Simulação da lógica do main.go
	mux.HandleFunc("/_teste/", func(w http.ResponseWriter, r *http.Request) {
		http.NotFound(w, r)
	})

	t.Run("Rotas /_teste/ retornam 404 quando MODO_TESTE=0", func(t *testing.T) {
		rotas := []string{"/_teste/reset", "/_teste/relogio"}
		for _, rota := range rotas {
			req := httptest.NewRequest("GET", rota, nil)
			rec := httptest.NewRecorder()
			mux.ServeHTTP(rec, req)

			if rec.Code != http.StatusNotFound {
				t.Errorf("rota %s: esperava 404, recebeu %d", rota, rec.Code)
			}
		}
	})
}

